def two_sum_sorted(numbers, target):
    left = 0
    right = len(numbers) - 1

    while left < right:
        current_sum = numbers[left] + numbers[right]
        print(f'Inspecting indices ({left}, {right}): {numbers[left]} + {numbers[right]} = {current_sum}')

        if current_sum == target:
            return (left, right)
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return None

# Demo run
sorted_arr = [2, 7, 11, 15]
target_sum = 9
result = two_sum_sorted(sorted_arr, target_sum)
print(f'Target {target_sum} found at indices: {result}')

